=const yaml = require('js-yaml');
// Parse the binary file as YAML
const content = $binary['data'].toString('utf8');
try {
  const parsed = yaml.load(content);
  return {
    json: {
      projects: Object.keys(parsed.projects || {}),
      tags: {},
      nested_meta: []
    }
  };
} catch(e) {
  // Fallback: parse as flat lines
  const lines = content.split('\n');
  const projects = lines.filter(l => l.startsWith('  ') && !l.includes(':') && !l.trim().startsWith('#')).map(l => l.trim());
  return { json: { projects, tags: {}, nested_meta: [], parse_error: e.message } };
}

=const content = $binary['data'].toString('utf8');
const lines = content.split('\n');
let inWorkspace = false;
let inMembers = false;
const members = [];
for (const line of lines) {
  if (line === '[workspace]') { inWorkspace = true; continue; }
  if (inWorkspace && line.startsWith('members')) { inMembers = true; continue; }
  if (inMembers) {
    const m = line.trim().replace(/,?$/, '');
    if (m && !m.startsWith('#')) members.push(m);
    if (line.includes(']') && line.trim() !== ']') break;
  }
}
return { json: { workspace_members: members } };

// Merge and prioritize all discovered work items
const metaProjects = $json.projects || [];
const cargoMembers = $json.workspace_members || [];

// Generate backlog items from each source
const items = [];

// Each .meta.yaml project becomes a map/automate epic item
for (const proj of metaProjects) {
  items.push({
    id: `map-${proj.toLowerCase()}`,
    title: `Map ${proj} repo structure and dependencies`,
    status: 'todo',
    epic: 'A-MapMetaCodebase',
    priority: 'P2',
    depends_on: [],
    automation_type: 'both',
    source: 'meta_yaml'
  });
}

// Cargo workspace members become verify items
for (const member of cargoMembers) {
  items.push({
    id: `verify-${member.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
    title: `Verify ${member} build/test chain`,
    status: 'todo',
    epic: 'B-ToolchainAutomation',
    priority: 'P1',
    depends_on: items.filter(i => i.title.includes('foundation') || i.id.startsWith('map-meta-core')).map(i => i.id),
    automation_type: 'n8n_workflow',
    source: 'cargo_workspace'
  });
}

// Deduplicate and assign priorities
const seen = new Set();
for (const item of items) {
  const key = `${item.epic}-${item.id}`;
  if (!seen.has(key)) {
    seen.add(key);
    // Foundation crates are always P0
    if (['meta_core', 'loop_lib', 'meta_plugin_protocol'].includes(item.id.toLowerCase().replace('verify-', '').replace(/[-_]/g, '_'))) {
      item.priority = 'P0';
    }
  }
}

return { json: { items } };

=const fs = require('fs');
const path = require('path');
const WS = process.env.META_ROOT + '/n8n/_workspace';

let md = '# n8n-loop Backlog\n';
md += `## Updated: ${new Date().toISOString()}\n\n`;

// Group by epic
const epics = {};
for (const item of $json.items) {
  if (!epics[item.epic]) epics[item.epic] = [];
  epics[item.epic].push(item);
}

for (const [epic, items] of Object.entries(epics)) {
  md += `### ${epic}\n\n`;
  for (const item of items) {
    const checked = item.status === 'done' ? 'x' : ' ';
    md += `- [${checked}] ${item.id}: ${item.title}` + '\n';
    md += `  - automation_type: ${item.automation_type}` + '\n';
    md += `  - verify_gates: cargo_check, bun_test, lint` + '\n';
    if (item.depends_on.length > 0) {
      md += `  - depends_on: ${JSON.stringify(item.depends_on)}` + '\n';
    }
    md += '\n';
  }
}

fs.writeFileSync(path.join(WS, 'backlog.md'), md);
return { json: { backlog_written: true, items_count: $json.items.length } };
